package com.northstar.crm.ui;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.AccountService;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;@Route(value="profile",layout=MainLayout.class)@PageTitle("Profile · Northstar")@PermitAll public class ProfileView extends VerticalLayout {public ProfileView(ActorResolver actors,AccountService accounts){var user=actors.current();var name=new TextField("Display name");name.setValue(user.getDisplayName());name.setMaxLength(100);var email=new TextField("Email");email.setValue(user.getEmail());email.setReadOnly(true);var role=new TextField("Role");role.setValue(UiKit.human(user.getRole()));role.setReadOnly(true);var save=UiKit.primary("Save changes",e->{try{accounts.updateProfile(name.getValue());UiKit.success("Profile updated");}catch(Exception ex){UiKit.error(ex);}});var panel=new VerticalLayout(name,email,role,save);panel.addClassName("panel");panel.setMaxWidth("620px");add(UiKit.page("YOUR ACCOUNT","Profile","Keep your name current. Email and role changes require platform administration.",panel));setPadding(false);}}
